import { useEffect } from 'react';
import { PieChart, Pie, Cell, BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { useEvents } from '../context/EventContext';
import { useAuth } from '../context/AuthContext';
import { useDarkMode } from '../context/DarkModeContext';
import EventCard from '../components/EventCard';

const COLORS = ['#6366f1', '#f59e0b', '#10b981', '#ec4899', '#06b6d4', '#f97316', '#8b5cf6'];

const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const DEFAULT_STATS = {
  overview: { totalEvents: 0, totalRegistrations: 0, totalRevenue: 0, avgCapacityUsed: 0 },
  byCategory: [],
  byStatus: [],
  byMonth: [],
};

const QUOTES = [
  'Every great event starts with a great plan.',
  'Create experiences people remember for a lifetime.',
  'The best events bring people together.',
];

function StatCard({ label, value, sub, color, theme }) {
  return (
    <div style={{
      background: theme.surface, borderRadius: 12, padding: '20px 24px',
      border: `1px solid ${theme.border}`, boxShadow: theme.cardShadow,
      borderLeft: `4px solid ${color}`, transition: 'all 0.3s',
    }}>
      <div style={{ fontSize: 13, color: theme.textMuted, marginBottom: 4 }}>{label}</div>
      <div style={{ fontSize: 28, fontWeight: 700, color: theme.text }}>{value}</div>
      {sub && <div style={{ fontSize: 12, color: theme.textFaint, marginTop: 2 }}>{sub}</div>}
    </div>
  );
}

export default function Dashboard() {
  const { stats, events, loading, fetchStats, fetchEvents } = useEvents();
  const { user } = useAuth();
  const { theme } = useDarkMode();
  const quote = QUOTES[new Date().getDay() % QUOTES.length];

  useEffect(() => {
    fetchStats();
    fetchEvents({ sort: '-createdAt', limit: 6 });
  }, [fetchEvents, fetchStats]);

  const { overview, byCategory, byStatus, byMonth } = stats || DEFAULT_STATS;

  const monthData = byMonth.map((m) => ({
    name: MONTHS[m._id.month - 1],
    Events: m.count,
    Registrations: m.registrations,
  }));

  const categoryData = byCategory.map((c) => ({ name: c._id, value: c.count }));

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
      {/* Welcome banner */}
      <div style={{
        background: 'linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%)',
        borderRadius: 14, padding: '22px 28px', color: '#fff',
      }}>
        <h2 style={{ margin: 0, fontSize: 20, fontWeight: 700 }}>Welcome back, {user?.name?.split(' ')[0]} 👋</h2>
        <p style={{ margin: '6px 0 0', opacity: 0.85, fontSize: 14 }}>"{quote}"</p>
      </div>

      {/* Stat cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: 16 }}>
        <StatCard label="Total Events" value={overview.totalEvents} color="#6366f1" theme={theme} />
        <StatCard label="Total Registrations" value={overview.totalRegistrations} color="#10b981" theme={theme} />
        <StatCard label="Total Revenue" value={`₹${overview.totalRevenue.toLocaleString()}`} color="#f59e0b" theme={theme} />
        <StatCard
          label="Avg Capacity Used"
          value={`${Math.round((overview.avgCapacityUsed || 0) * 100)}%`}
          color="#ec4899"
          theme={theme}
        />
      </div>

      {/* Charts row */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: 20 }}>
        {/* Events by category — Pie */}
        <div style={{ background: theme.surface, borderRadius: 12, padding: 20, border: `1px solid ${theme.border}`, transition: 'all 0.3s' }}>
          <h3 style={{ margin: '0 0 16px', fontSize: 15, fontWeight: 600, color: theme.text }}>Events by Category</h3>
          {categoryData.length === 0 ? (
            <p style={{ color: theme.textFaint, fontSize: 14 }}>No data yet</p>
          ) : (
            <ResponsiveContainer width="100%" height={220}>
              <PieChart>
                <Pie data={categoryData} cx="50%" cy="50%" innerRadius={55} outerRadius={85}
                  dataKey="value" nameKey="name" label={({ name, value }) => `${name}: ${value}`} labelLine={false}>
                  {categoryData.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
                </Pie>
                <Tooltip contentStyle={{ background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 8, color: theme.text }} />
              </PieChart>
            </ResponsiveContainer>
          )}
        </div>

        {/* Events by status — small pills */}
        <div style={{ background: theme.surface, borderRadius: 12, padding: 20, border: `1px solid ${theme.border}`, transition: 'all 0.3s' }}>
          <h3 style={{ margin: '0 0 16px', fontSize: 15, fontWeight: 600, color: theme.text }}>Events by Status</h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            {byStatus.map((s, i) => (
              <div key={s._id} style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                <div style={{ width: 12, height: 12, borderRadius: '50%', background: COLORS[i % COLORS.length], flexShrink: 0 }} />
                <span style={{ flex: 1, fontSize: 14, color: theme.textSecondary, textTransform: 'capitalize' }}>{s._id}</span>
                <span style={{ fontWeight: 700, fontSize: 16, color: theme.text }}>{s.count}</span>
              </div>
            ))}
            {byStatus.length === 0 && <p style={{ color: theme.textFaint, fontSize: 14 }}>No data yet</p>}
          </div>
        </div>
      </div>

      {/* Monthly Bar chart */}
      <div style={{ background: theme.surface, borderRadius: 12, padding: 20, border: `1px solid ${theme.border}`, transition: 'all 0.3s' }}>
        <h3 style={{ margin: '0 0 16px', fontSize: 15, fontWeight: 600, color: theme.text }}>Monthly Activity (Last 12 Months)</h3>
        {monthData.length === 0 ? (
          <p style={{ color: theme.textFaint, fontSize: 14 }}>No data yet</p>
        ) : (
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={monthData} margin={{ top: 4, right: 8, bottom: 0, left: -10 }}>
              <XAxis dataKey="name" tick={{ fontSize: 12, fill: theme.textMuted }} />
              <YAxis tick={{ fontSize: 12, fill: theme.textMuted }} allowDecimals={false} />
              <Tooltip contentStyle={{ background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 8, color: theme.text }} />
              <Legend />
              <Bar dataKey="Events" fill="#6366f1" radius={[4, 4, 0, 0]} />
              <Bar dataKey="Registrations" fill="#10b981" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        )}
      </div>

      <div style={{ background: theme.surface, borderRadius: 12, padding: 20, border: `1px solid ${theme.border}`, transition: 'all 0.3s' }}>
        <div style={{ marginBottom: 16 }}>
          <h3 style={{ margin: 0, fontSize: 15, fontWeight: 600, color: theme.text }}>Recent Events</h3>
          <p style={{ margin: '6px 0 0', fontSize: 13, color: theme.textMuted }}>
            Latest events visible to all users and organisers.
          </p>
        </div>

        {loading ? (
          <p style={{ color: theme.textFaint, fontSize: 14 }}>Loading events...</p>
        ) : events.length === 0 ? (
          <p style={{ color: theme.textFaint, fontSize: 14 }}>No events available yet</p>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 16 }}>
            {events.map((event) => <EventCard key={event._id} event={event} />)}
          </div>
        )}
      </div>
    </div>
  );
}
